// Field minimization (same convention as Triage Pipeline's 'Build triage
// prompt'): only subject + a truncated plain-text body + received_at ever
// leave this workflow toward LLM Gateway / Gemini -- never raw_payload or
// headers, which are not even part of this workflow's input in the first
// place (Execute Workflow Trigger only declares email_id/subject/body/received_at).
const input = $json || {};
const emailId = input.email_id;

// Malformed input (null/missing subject, body, or received_at) must never
// throw here (mirrors AC2's no-content-email case, and any malformed row).
const subject = input.subject === null || input.subject === undefined ? '' : String(input.subject);
const bodyRaw = input.body === null || input.body === undefined ? '' : String(input.body);
const receivedAt = input.received_at === null || input.received_at === undefined ? '' : String(input.received_at);
const truncatedBody = bodyRaw.slice(0, 2000);

const systemPrompt = 'You are an email action-item extraction assistant. Read the email and decide whether it contains an actionable request or commitment -- something the recipient needs to do. If it does, set has_task to true and extract a short task_text describing what needs to be done. If it does not, set has_task to false and omit task_text and deadline entirely. Today\'s date / the email\'s reference date is ' + receivedAt + '. Only include a deadline if a date for the task is clearly and confidently stated in the email, or unambiguously implied relative to the reference date above (for example "by Friday") -- resolve any such relative date against the reference date, do not invent one. If you cannot produce a confident deadline in YYYY-MM-DD format, omit the deadline field entirely rather than guess. Respond only with JSON matching the given schema.';

const userContent = `Email received: ${receivedAt}\n\nSubject: ${subject}\n\nBody:\n${truncatedBody}`;

// task_text is constrained to a plain string; deadline is pinned to
// YYYY-MM-DD via pattern as defense-in-depth (the actual enforcement point
// is 'Validate extraction result' below, not this schema).
const responseSchema = {
  type: 'object',
  properties: {
    has_task: {
      type: 'boolean',
    },
    task_text: {
      type: 'string',
    },
    deadline: {
      type: 'string',
      pattern: '^\\d{4}-\\d{2}-\\d{2}$',
    },
  },
  required: ['has_task'],
};

return {
  json: {
    email_id: emailId,
    system_prompt: systemPrompt,
    user_content: userContent,
    response_schema: responseSchema,
  },
};

// Never throws unhandled (same convention as Triage Pipeline's 'Validate
// triage result') -- any unexpected error still produces an { outcome:
// 'error', ... } item that routes to the error-write branch.
try {
  const gatewayResult = $json || {};

  // .first() rather than .item: with multiple items in flight (e.g. running
  // this workflow against more than one pinned fixture item at once during
  // testing), .item cannot resolve a single unambiguous upstream match and
  // n8n throws 'Multiple matches' -- same bug 004-triage hit and fixed this
  // way in Triage Pipeline's 'Format success output'/'Format failure output'.
  let emailId;
  try {
    emailId = $('Build extraction prompt').first().json.email_id;
  } catch (refErr) {
    emailId = null;
  }

  if (!gatewayResult.success) {
    const message = gatewayResult.error || 'LLM Gateway call failed';
    return { json: { outcome: 'error', email_id: emailId, error: String(message) } };
  }

  const data = gatewayResult.data || {};

  // FR9: no actionable request found is the common, successful case -- no
  // write at all, not an error.
  if (!data.has_task) {
    return { json: { outcome: 'none', email_id: emailId } };
  }

  const taskText = data.task_text;
  if (typeof taskText !== 'string' || taskText.trim().length === 0) {
    return {
      json: {
        outcome: 'error',
        email_id: emailId,
        error: 'has_task true but task_text missing/empty',
      },
    };
  }

  const deadline = data.deadline;
  const hasDeadline = deadline !== undefined && deadline !== null && deadline !== '';

  if (hasDeadline) {
    if (typeof deadline !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(deadline)) {
      return {
        json: {
          outcome: 'error',
          email_id: emailId,
          error: `deadline '${deadline}' does not match YYYY-MM-DD`,
        },
      };
    }
    return { json: { outcome: 'task', email_id: emailId, task_text: taskText, deadline } };
  }

  return { json: { outcome: 'task', email_id: emailId, task_text: taskText, deadline: null } };
} catch (err) {
  let emailId = null;
  try {
    emailId = $('Build extraction prompt').first().json.email_id;
  } catch (refErr) {
    emailId = null;
  }
  return {
    json: {
      outcome: 'error',
      email_id: emailId,
      error: (err && err.message) || 'Unknown Action Extraction error',
    },
  };
}

// .first() rather than .item -- see 'Validate extraction result' node's
// note: .item cannot resolve a single unambiguous upstream match when
// multiple items are in flight, confirmed live during 004-triage AC testing.
const emailId = $('Validate extraction result').first().json.email_id;
return { json: { email_id: emailId, extracted: true } };

// FR9: no actionable request found -- no DB write at all, just a minimal
// output. .first() rather than .item -- see 'Validate extraction result'
// node's note.
const emailId = $('Validate extraction result').first().json.email_id;
return { json: { email_id: emailId, extracted: false } };

// .first() rather than .item -- see 'Validate extraction result' node's
// note: .item cannot resolve a single unambiguous upstream match when
// multiple items are in flight, confirmed live during 004-triage AC testing.
const emailId = $('Validate extraction result').first().json.email_id;
return { json: { email_id: emailId, extracted: false } };
